import fs from 'node:fs';import crypto from 'node:crypto';import path from 'node:path';
const bytes=fs.readFileSync('.helm-review-manifest.json'),hash=x=>crypto.createHash('sha256').update(x).digest('hex');if(process.argv[2]&&hash(bytes)!==process.argv[2])throw Error('Pinned review bundle manifest mismatch');const m=JSON.parse(bytes);for(const [file,sha] of Object.entries(m.files)){if(path.isAbsolute(file)||file.split('/').includes('..')||hash(fs.readFileSync(file))!==sha)throw Error('Review source identity mismatch: '+file);}console.log(JSON.stringify({classification:'DEDICATED_REVIEW_BUNDLE_NOT_PRODUCTION_CHECKOUT',files:Object.keys(m.files).length,manifestSha256:hash(bytes),release:0,rollout:0}));
